import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

const nonnegativeSafeInteger = value => Number.isSafeInteger(value) && value >= 0;

export function packContext(sections, maxBytes) {
  if (!nonnegativeSafeInteger(maxBytes)) {
    throw new Error('maxBytes must be a nonnegative safe integer');
  }
  if (!Array.isArray(sections)) throw new Error('sections must be a dense array');

  const ids = new Set();
  const entries = [];
  // Validate and snapshot all fields before considering any budget decisions.
  for (let index = 0; index < sections.length; index++) {
    if (!Object.hasOwn(sections, index)) throw new Error('sections must be dense');
    const section = sections[index];
    if (section === null || typeof section !== 'object' || Array.isArray(section)) {
      throw new Error('Each section must be an object');
    }
    const { id, text, priority, required } = section;
    if (typeof id !== 'string' || id.length === 0 || ids.has(id)) {
      throw new Error('Section IDs must be unique nonempty strings');
    }
    if (typeof text !== 'string' || !nonnegativeSafeInteger(priority) ||
        typeof required !== 'boolean') {
      throw new Error('Invalid section fields');
    }
    ids.add(id);
    entries.push({ id, text, priority, required, index });
  }

  for (const entry of entries) {
    entry.frame = '### ' + JSON.stringify(entry.id) + '\n' + entry.text + '\n';
    entry.cost = Buffer.byteLength(entry.frame, 'utf8');
  }
  let remaining = maxBytes;
  const chosen = [];
  const include = entry => {
    remaining -= entry.cost;
    entry.selected = true;
    chosen.push(entry);
  };
  for (const entry of entries) {
    if (!entry.required) continue;
    if (entry.cost > remaining) throw new Error('Required sections exceed maxBytes');
    include(entry);
  }
  const optional = entries.filter(entry => !entry.required);
  optional.sort((a, b) => b.priority - a.priority || a.index - b.index);
  for (const entry of optional) {
    if (entry.cost <= remaining) include(entry);
  }
  const text = chosen.map(entry => entry.frame).join('');
  return {
    text,
    bytes: Buffer.byteLength(text, 'utf8'),
    included: chosen.map(entry => entry.id),
    omitted: entries.filter(entry => !entry.required && !entry.selected).map(entry => entry.id)
  };
}

function main() {
  try {
    if (process.argv.length !== 3) throw new Error('Usage: node context-packet.js INPUT_JSON_FILE');
    const input = JSON.parse(readFileSync(process.argv[2], 'utf8'));
    if (input === null || typeof input !== 'object' || Array.isArray(input)) {
      throw new Error('Input must be an object containing sections and maxBytes');
    }
    const result = packContext(input.sections, input.maxBytes);
    process.stdout.write(JSON.stringify(result) + '\n');
  } catch (error) {
    process.stderr.write((error instanceof Error ? error.message : String(error)) + '\n');
    process.exitCode = 2;
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  main();
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { packContext } from '../context-packet.js';

const section = (id, text = '', priority = 0, required = false) => ({ id, text, priority, required });
const frame = s => '### ' + JSON.stringify(s.id) + '\n' + s.text + '\n';
const cost = s => Buffer.byteLength(frame(s), 'utf8');

test('numeric safe-integer boundaries and complete validation', () => {
  assert.deepEqual(packContext([], Number.MAX_SAFE_INTEGER), { text: '', bytes: 0, included: [], omitted: [] });
  assert.deepEqual(packContext([section('ok', '', Number.MAX_SAFE_INTEGER)], 100).included, ['ok']);
  const invalidNumbers = [-1, 0.5, NaN, Infinity, -Infinity, Number.MAX_SAFE_INTEGER + 1, '0', null, undefined, true, 0n];
  for (const value of invalidNumbers) {
    assert.throws(() => packContext([], value), Error);
    assert.throws(() => packContext([{ ...section('bad'), priority: value }], 0), Error);
  }
  for (const input of [null, undefined, {}, 'abc', new Array(1), [null], [[]], [false]]) {
    assert.throws(() => packContext(input, 0), Error);
  }
  for (const field of ['id', 'text', 'priority', 'required']) {
    const missing = section('missing');
    delete missing[field];
    assert.throws(() => packContext([missing], 0), Error);
    assert.throws(() => packContext([{ ...section('bad'), [field]: undefined }], 0), Error);
  }
  for (const invalid of [
    { ...section('x'), id: '' }, { ...section('x'), id: 1 },
    { ...section('x'), text: null }, { ...section('x'), text: new String('x') },
    { ...section('x'), required: 0 }, { ...section('x'), required: 'false' }
  ]) assert.throws(() => packContext([section('good'), invalid], 0), Error);
  assert.throws(() => packContext([section('__proto__'), section('__proto__')], 0), Error);
  // A later invalid field must be visited even after a required section cannot fit.
  const sentinel = new Error('validation reached');
  const invalid = { ...section('later'), get text() { throw sentinel; } };
  assert.throws(() => packContext([section('required', '', 0, true), invalid], 0), error => error === sentinel);
});

test('framing preserves arbitrary IDs, Unicode, whitespace, and source immutability', () => {
  const input = Object.freeze(['__proto__', 'A', 'a', ' \n\u0000雪"\\', '\ud800'].map(id =>
    Object.freeze({ ...section(id, ' \r\n é😀\u0000\ud800 '), ignored: 123 })));
  const expected = input.map(frame).join('');
  const bytes = Buffer.byteLength(expected);
  assert.deepEqual(packContext(input, bytes), {
    text: expected, bytes, included: input.map(s => s.id), omitted: []
  });
});

test('required input order, optional ties, skipping, and omitted input order', () => {
  const input = [
    section('low', 'x'.repeat(200), 1), section('b', '', 5),
    section('r1', '', 0, true), section('huge', 'x'.repeat(200), 10),
    section('c', '', 5), section('r2', '', 99, true), section('d', '', 4)
  ];
  const selected = [input[2], input[5], input[1], input[4]];
  const bytes = selected.reduce((sum, s) => sum + cost(s), 0);
  assert.deepEqual(packContext(input, bytes), {
    text: selected.map(frame).join(''), bytes,
    included: ['r1', 'r2', 'b', 'c'], omitted: ['low', 'huge', 'd']
  });
  assert.throws(() => packContext(input, cost(input[2]) + cost(input[5]) - 1), Error);
  assert.deepEqual(packContext([section('a'), section('b')], 0), {
    text: '', bytes: 0, included: [], omitted: ['a', 'b']
  });
});

test('CLI success, failures, and side-effect-free import', () => {
  const directory = mkdtempSync(join(tmpdir(), 'context-packet-'));
  const script = fileURLToPath(new URL('../context-packet.js', import.meta.url));
  const run = args => spawnSync(process.execPath, [script, ...args], { encoding: 'utf8' });
  const failure = args => {
    const result = run(args);
    assert.ifError(result.error);
    assert.equal(result.status, 2);
    assert.equal(result.stdout, '');
    assert.ok(result.stderr.length > 0);
  };
  try {
    const path = join(directory, 'input.json');
    const input = { sections: [section('雪', 'é', 0, true)], maxBytes: 100, ignored: true };
    writeFileSync(path, JSON.stringify(input));
    const result = run([path]);
    assert.ifError(result.error);
    assert.equal(result.status, 0);
    assert.equal(result.stderr, '');
    assert.equal(result.stdout, JSON.stringify(packContext(input.sections, input.maxBytes)) + '\n');
    failure([]);
    failure([path, path]);
    failure([join(directory, 'missing.json')]);
    failure([directory]);
    for (const text of ['{', 'null', '[]', '{}',
      JSON.stringify({ sections: input.sections, maxBytes: 0 }),
      JSON.stringify({ sections: [section('x', '', Number.MAX_SAFE_INTEGER + 1)], maxBytes: 0 })]) {
      writeFileSync(path, text);
      failure([path]);
    }
    const imported = spawnSync(process.execPath, ['--input-type=module', '-e',
      `await import(${JSON.stringify(new URL('../context-packet.js', import.meta.url).href)})`], { encoding: 'utf8' });
    assert.ifError(imported.error);
    assert.equal(imported.status, 0);
    assert.equal(imported.stdout, '');
    assert.equal(imported.stderr, '');
  } finally {
    rmSync(directory, { recursive: true, force: true });
  }
});

